from urllib.parse import quote


IGNORED_VALUES = {None, "", "all", "全部"}
VALID_CHANNELS = {"20", "21"}
VALID_SORTS = {"time", "hits", "score"}


def clean(value):
    if value in IGNORED_VALUES:
        return ""
    value = str(value).strip()
    if value in IGNORED_VALUES:
        return ""
    return value


def int_or_default(value, default):
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


def add_segment(segments, key, value, *, safe=""):
    value = clean(value)
    if value:
        segments.extend([key, quote(value, safe=safe)])


def execute(node_id, node_data, context):
    page_num = max(int_or_default(context.get("page_num") or 1, 1), 1)

    keyword = clean(context.get("keyword"))
    if keyword:
        context["list_path"] = "/search.html?wd=" + quote(keyword)
        return

    channel = clean(context.get("channel")) or "20"
    if channel not in VALID_CHANNELS:
        channel = "20"

    segments = []
    add_segment(segments, "class", context.get("class"))
    add_segment(segments, "year", context.get("year"))
    add_segment(segments, "letter", context.get("letter"), safe="-")

    sort_by = clean(context.get("by"))
    if sort_by in VALID_SORTS:
        segments.extend(["by", sort_by])

    if page_num > 1:
        segments.extend(["page", str(page_num)])

    path = f"/show/{channel}"
    if segments:
        path += "/" + "/".join(segments)
    context["list_path"] = path + ".html"

