import base64
import hashlib
from urllib.parse import quote

PLAYER_SALT = "YLwJVbXw77pk2eOrAnFdBo2c3mWkLtodMni2wk81GCnP94ZltW"


def gf_mul(a, b):
    p = 0
    for _ in range(8):
        if b & 1:
            p ^= a
        hi = a & 0x80
        a = (a << 1) & 0xFF
        if hi:
            a ^= 0x1B
        b >>= 1
    return p


def gf_pow(a, n):
    r = 1
    while n:
        if n & 1:
            r = gf_mul(r, a)
        a = gf_mul(a, a)
        n >>= 1
    return r


def rotl8(x, n):
    return ((x << n) | (x >> (8 - n))) & 0xFF


def make_sboxes():
    sbox = []
    for x in range(256):
        inv = 0 if x == 0 else gf_pow(x, 254)
        y = inv ^ rotl8(inv, 1) ^ rotl8(inv, 2) ^ rotl8(inv, 3) ^ rotl8(inv, 4) ^ 0x63
        sbox.append(y & 0xFF)
    inv_sbox = [0] * 256
    for i, v in enumerate(sbox):
        inv_sbox[v] = i
    return sbox, inv_sbox


SBOX, INV_SBOX = make_sboxes()


def expand_key(key):
    expanded = list(key)
    rcon = 1
    while len(expanded) < 176:
        temp = expanded[-4:]
        if len(expanded) % 16 == 0:
            temp = temp[1:] + temp[:1]
            temp = [SBOX[b] for b in temp]
            temp[0] ^= rcon
            rcon = gf_mul(rcon, 2)
        for b in temp:
            expanded.append(expanded[-16] ^ b)
    return [expanded[i:i + 16] for i in range(0, 176, 16)]


def add_round_key(state, key):
    for i in range(16):
        state[i] ^= key[i]


def inv_sub_bytes(state):
    for i, b in enumerate(state):
        state[i] = INV_SBOX[b]


def inv_shift_rows(state):
    old = state[:]
    for r in range(4):
        for c in range(4):
            state[r + 4 * c] = old[r + 4 * ((c - r) % 4)]


def inv_mix_columns(state):
    for c in range(4):
        i = 4 * c
        a0, a1, a2, a3 = state[i:i + 4]
        state[i] = gf_mul(a0, 14) ^ gf_mul(a1, 11) ^ gf_mul(a2, 13) ^ gf_mul(a3, 9)
        state[i + 1] = gf_mul(a0, 9) ^ gf_mul(a1, 14) ^ gf_mul(a2, 11) ^ gf_mul(a3, 13)
        state[i + 2] = gf_mul(a0, 13) ^ gf_mul(a1, 9) ^ gf_mul(a2, 14) ^ gf_mul(a3, 11)
        state[i + 3] = gf_mul(a0, 11) ^ gf_mul(a1, 13) ^ gf_mul(a2, 9) ^ gf_mul(a3, 14)


def decrypt_block(block, round_keys):
    state = list(block)
    add_round_key(state, round_keys[10])
    for round_index in range(9, 0, -1):
        inv_shift_rows(state)
        inv_sub_bytes(state)
        add_round_key(state, round_keys[round_index])
        inv_mix_columns(state)
    inv_shift_rows(state)
    inv_sub_bytes(state)
    add_round_key(state, round_keys[0])
    return bytes(state)


def aes_cbc_decrypt(ciphertext, key, iv):
    round_keys = expand_key(key)
    prev = iv
    out = bytearray()
    for i in range(0, len(ciphertext), 16):
        block = ciphertext[i:i + 16]
        plain = decrypt_block(block, round_keys)
        out.extend(a ^ b for a, b in zip(plain, prev))
        prev = block
    pad = out[-1]
    if 0 < pad <= 16 and out[-pad:] == bytes([pad]) * pad:
        del out[-pad:]
    return bytes(out)


def player_seed(viewport_id, charset_id):
    viewport = (viewport_id or "").replace("now_", "")
    charset = (charset_id or "").replace("now_", "")
    pairs = []
    for order, char in zip(charset, viewport):
        if order.isdigit():
            pairs.append((int(order), char))
    return "".join(char for _, char in sorted(pairs))



def proxied_media_url(url):
    if url.startswith(("http://", "https://")):
        return "/_api/media/proxy?url=" + quote(url, safe="")
    return url

def video_type(url):
    lower = (url or "").split("?", 1)[0].lower()
    if ".m3u8" in lower:
        return "hls"
    if ".flv" in lower:
        return "flv"
    return "mp4"


def execute(node_id, node_data, context):
    cipher_url = context.get("cipher_url") or ""
    seed = player_seed(context.get("viewport_id"), context.get("charset_id"))
    secret = hashlib.md5((seed + PLAYER_SALT).encode()).hexdigest()
    key = secret[16:].encode()
    iv = secret[:16].encode()
    media_url = aes_cbc_decrypt(base64.b64decode(cipher_url), key, iv).decode()

    context["source_video_url"] = media_url
    context["video_url"] = proxied_media_url(media_url)
    context["video_type"] = video_type(media_url)
    context["danmakus"] = []

